function GetStaticTextureData(x,y,w=64,h=64) {
  let img=new Int32Array(w*h);
let i=0;
  
  for (let yy=0;yy<h;yy++)
  {
     let yyy=(yy+y)*StaticTexture_WIDTH;

     for (let xx=0;xx<w;xx++)   
    {
        let xxx=(xx+x);
        let rgb =StaticTexture[yyy+xxx];
             a=RGBToAlpha(rgb)
             r=RGBToRed(rgb)
             g=RGBToGreen(rgb)
             b=RGBToBlue(rgb)  
             img[xx+yy*w]= RGB(a,b,g);
             
    }
  }
  return img;
}

function ConvertToPNG() {
  
   var canvas = new Canvas("texture_canvas",64,64);
  for (let x=0;x<4;x++)
  {
    
    for (let y=0;y<4;y++)
    {
  let temp=GetStaticTextureData(x*64,y*64);
        for (let i=0;i<64*64;i++)canvas.GetActiveBuffer()[i]=temp[i];
     canvas.Redraw();
          canvas.SaveAsImg("Texture"+x.toString()+"x"+y.toString());
     wait(100000);
    }
  }
  
}